from mic_chrono_part1 import make_chrono_q

questions = []

# MIC_CHRONO_018
questions.append(make_chrono_q(
    "MIC_CHRONO_018", "Chronology",
    "Arrange the following milestones in the dual-role functioning of the Constituent Assembly in correct chronological order:\n1. Constituent Assembly functions purely as a Constitution-framing body\n2. Indian Independence Act 1947 grants legislative powers to the Assembly\n3. G.V. Mavlankar elected Speaker as Assembly meets for the first time as a Legislative body\n4. Dissolution of Constituent Assembly role and continuance as Provisional Parliament until 1952 general elections",
    "அரசியலமைப்பு அவையின் இரட்டைச் செயல்பாட்டு மைல்கற்களை சரியான காலவரிசையில் அமைக்கவும்:\n1. அரசியலமைப்பு அவை முற்றிலும் அரசியலமைப்பை உருவாக்கும் அமைப்பாகச் செயல்படுதல்\n2. 1947 இந்திய சுதந்திரச் சட்டம் அவைக்கு சட்டமன்ற அதிகாரங்களை வழங்குதல்\n3. அவை முதன்முறையாக சட்டமன்றமாகக் கூடும் போது ஜி.வி. மாவ்லங்கார் சபாநாயகராகத் தேர்ந்தெடுக்கப்படுதல்\n4. அரசியலமைப்பு அவைப் பங்கு முடிவுக்கு வந்து 1952 பொதுத் தேர்தல் வரை தற்காலிக நாடாளுமன்றமாகத் தொடருதல்",
    ["Constituent Assembly functions purely as a Constitution-framing body", "Indian Independence Act 1947 grants legislative powers to the Assembly", "G.V. Mavlankar elected Speaker as Assembly meets for the first time as a Legislative body", "Dissolution of Constituent Assembly role and continuance as Provisional Parliament until 1952 general elections"],
    ["அரசியலமைப்பு அவை முற்றிலும் அரசியலமைப்பை உருவாக்கும் அமைப்பாகச் செயல்படுதல்", "1947 இந்திய சுதந்திரச் சட்டம் அவைக்கு சட்டமன்ற அதிகாரங்களை வழங்குதல்", "அவை முதன்முறையாக சட்டமன்றமாகக் கூடும் போது ஜி.வி. மாவ்லங்கார் சபாநாயகராகத் தேர்ந்தெடுக்கப்படுதல்", "அரசியலமைப்பு அவைப் பங்கு முடிவுக்கு வந்து 1952 பொதுத் தேர்தல் வரை தற்காலிக நாடாளுமன்றமாகத் தொடருதல்"],
    "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (Purely Constituent, Dec 1946-July 1947) -> 2 (Independence Act passed, July 18, 1947) -> 3 (Mavlankar elected Speaker, Nov 17, 1947) -> 4 (Provisional Parliament till May 1952).",
    "சரியான காலவரிசை: 1 (அரசியலமைப்பு அவை மட்டும், டிச 1946-ஜூலை 1947) -> 2 (சுதந்திரச் சட்டம், ஜூலை 18, 1947) -> 3 (மாவ்லங்கார் சபாநாயகராகத் தேர்வு, நவ 17, 1947) -> 4 (தற்காலிக நாடாளுமன்றமாக மே 1952 வரை தொடர்தல்).",
    "Correct. 1 (Dec 1946) -> 2 (July 1947) -> 3 (Nov 17, 1947) -> 4 (Jan 1950 - May 1952) is exact.", "சரி. 1 (டிச 1946) -> 2 (ஜூலை 1947) -> 3 (நவ 17, 1947) -> 4 (மே 1952 வரை) துல்லியமானது.",
    "Incorrect. Purely constituent phase (1) preceded Independence Act (2).", "தவறு. அரசியலமைப்பு அவை மட்டும் செயல்பட்ட கட்டம் (1) சுதந்திரச் சட்டத்திற்கு முந்தியது (2).",
    "Incorrect. Independence Act (2) granted powers before Mavlankar was elected Speaker (3).", "தவறு. சுதந்திரச் சட்டம் (2) மாவ்லங்கார் சபாநாயகர் தேர்தலுக்கு முந்தியது (3).",
    "Incorrect. Purely constituent phase (1) was the earliest.", "தவறு. அரசியலமைப்பு அவை மட்டும் செயல்பட்ட கட்டம் (1) மிக முந்தையது.",
    "TNPSC Trap: Dual functions started on Nov 17, 1947 (when G.V. Mavlankar was elected Speaker of the Legislative Assembly).",
    "TNPSC பொறி: இரட்டைச் செயல்பாடுகள் நவம்பர் 17, 1947 இல் தொடங்கின (ஜி.வி. மாவ்லங்கார் சட்டமன்ற சபாநாயகராகத் தேர்ந்தெடுக்கப்பட்ட போது).",
    "The Provisional Parliament enacted key laws like the Representation of the People Acts (1950 and 1951) before the 1st general elections.",
    "தற்காலிக நாடாளுமன்றம் 1வது பொதுத் தேர்தலுக்கு முன் மக்கள் பிரதிநிதித்துவச் சட்டங்களை (1950, 1951) இயற்றியது.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Constituent Assembly as Legislature"]
))

# MIC_CHRONO_019
questions.append(make_chrono_q(
    "MIC_CHRONO_019", "Chronology",
    "Arrange the following legislative enactments and repeal events in correct chronological order:\n1. Enactment of the Government of India Act, 1935 by British Parliament\n2. Enactment of the Indian Independence Act, 1947 by British Parliament\n3. Enactment of the Abolition of Privy Council Jurisdiction Act by Constituent Assembly\n4. Repeal of Government of India Act 1935 & Indian Independence Act 1947 under Article 395",
    "பின்வரும் சட்ட இயற்றல்கள் மற்றும் ரத்து நிகழ்வுகளை சரியான காலவரிசையில் அமைக்கவும்:\n1. பிரிட்டிஷ் நாடாளுமன்றத்தால் 1935 இந்திய அரசுச் சட்டம் இயற்றப்படுதல்\n2. பிரிட்டிஷ் நாடாளுமன்றத்தால் 1947 இந்திய சுதந்திரச் சட்டம் இயற்றப்படுதல்\n3. அரசியலமைப்பு அவையால் பிரிவி கவுன்சில் அதிகார வரம்பு ஒழிப்புச் சட்டம் இயற்றப்படுதல்\n4. சரத்து 395 இன் கீழ் 1935 இந்திய அரசுச் சட்டம் & 1947 இந்திய சுதந்திரச் சட்டம் ரத்து செய்யப்படுதல்",
    ["Enactment of the Government of India Act, 1935 by British Parliament", "Enactment of the Indian Independence Act, 1947 by British Parliament", "Enactment of the Abolition of Privy Council Jurisdiction Act by Constituent Assembly", "Repeal of Government of India Act 1935 & Indian Independence Act 1947 under Article 395"],
    ["பிரிட்டிஷ் நாடாளுமன்றத்தால் 1935 இந்திய அரசுச் சட்டம் இயற்றப்படுதல்", "பிரிட்டிஷ் நாடாளுமன்றத்தால் 1947 இந்திய சுதந்திரச் சட்டம் இயற்றப்படுதல்", "அரசியலமைப்பு அவையால் பிரிவி கவுன்சில் அதிகார வரம்பு ஒழிப்புச் சட்டம் இயற்றப்படுதல்", "சரத்து 395 இன் கீழ் 1935 இந்திய அரசுச் சட்டம் & 1947 இந்திய சுதந்திரச் சட்டம் ரத்து செய்யப்படுதல்"],
    "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (GoI Act 1935) -> 2 (Indian Independence Act, July 1947) -> 3 (Abolition of Privy Council Jurisdiction Act, Sept 1949) -> 4 (Repeal under Art 395, Jan 26, 1950).",
    "சரியான காலவரிசை: 1 (1935 அரசுச் சட்டம்) -> 2 (1947 சுதந்திரச் சட்டம்) -> 3 (1949 பிரிவி கவுன்சில் ஒழிப்புச் சட்டம்) -> 4 (சரத்து 395 ரத்து, ஜன 26, 1950).",
    "Correct. 1 (1935) -> 2 (July 1947) -> 3 (Sept 1949) -> 4 (Jan 26, 1950) is exact.", "சரி. 1 (1935) -> 2 (ஜூலை 1947) -> 3 (செப் 1949) -> 4 (ஜன 26, 1950) துல்லியமானது.",
    "Incorrect. GoI Act 1935 (1) was enacted long before Indian Independence Act 1947 (2).", "தவறு. 1935 அரசுச் சட்டம் (1) 1947 சுதந்திரச் சட்டத்திற்கு முந்தியது (2).",
    "Incorrect. Indian Independence Act 1947 (2) was enacted before Privy Council Act 1949 (3).", "தவறு. 1947 சுதந்திரச் சட்டம் (2) 1949 பிரிவி கவுன்சில் சட்டத்திற்கு முந்தியது (3).",
    "Incorrect. GoI Act 1935 (1) was the earliest among these.", "தவறு. 1935 அரசுச் சட்டம் (1) மிக முந்தையது.",
    "TNPSC Trap: Article 395 explicitly repealed the 1935 GoI Act and 1947 Independence Act, BUT excepted the Abolition of Privy Council Jurisdiction Act 1949.",
    "TNPSC பொறி: சரத்து 395 1935 அரசுச் சட்டம் மற்றும் 1947 சுதந்திரச் சட்டத்தை ரத்து செய்தது, ஆனால் 1949 பிரிவி கவுன்சில் ஒழிப்புச் சட்டத்தை விலக்கியது.",
    "The Abolition of Privy Council Jurisdiction Act 1949 abolished appeals to the British Privy Council and transferred pending appeals to the Federal Court (later Supreme Court).",
    "1949 பிரிவி கவுன்சில் ஒழிப்புச் சட்டம் பிரிட்டிஷ் பிரிவி கவுன்சிலுக்கான மேல்முறையீடுகளை ரத்து செய்து கூட்டாட்சி நீதிமன்றத்திற்கு (பின்னர் உச்ச நீதிமன்றம்) மாற்றியது.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Enforcement of Constitution", "Constitutional Facts"]
))

# MIC_CHRONO_020
questions.append(make_chrono_q(
    "MIC_CHRONO_020", "Chronology",
    "Which of the following represents the correct sequence of events regarding the calligraphy, decoration, signing, and preservation of the Constitution?\n1. Commissioning of Prem Behari Narain Raizada to calligraph the original English manuscript\n2. Illumination and artistic decoration of manuscript pages by Shantiniketan artists under Nandalal Bose\n3. Signing of the three handwritten and printed copies by 284 members of the Assembly\n4. Preservation of original handwritten copies in helium-filled glass cases in Parliament Library",
    "அரசியலமைப்பின் கையெழுத்து, அலங்காரம், கையெழுத்திடுதல் மற்றும் பாதுகாப்பு நிகழ்வுகளின் சரியான வரிசை எது?\n1. ஆங்கில அசல் கையெழுத்துப் பிரதியை எழுத பிரேம் பிஹாரி நரேன் ரைசாதா நியமிக்கப்படுதல்\n2. நந்தலால் போஸ் தலைமையில் சாந்திநிகேதன் கலைஞர்களால் பக்கங்கள் அலங்கரிக்கப்பட்டு ஒளிவூட்டப்படுதல்\n3. அவையின் 284 உறுப்பினர்கள் 3 அசல் பிரதிகளில் கையெழுத்திடுதல்\n4. நாடாளுமன்ற நூலகத்தில் ஹீலியம் நிரப்பப்பட்ட கண்ணாடிப் பெட்டிகளில் அசல் பிரதிகள் பாதுகாப்பபடுதல்",
    ["Commissioning of Prem Behari Narain Raizada to calligraph the original English manuscript", "Illumination and artistic decoration of manuscript pages by Shantiniketan artists under Nandalal Bose", "Signing of the three handwritten and printed copies by 284 members of the Assembly", "Preservation of original handwritten copies in helium-filled glass cases in Parliament Library"],
    ["ஆங்கில அசல் கையெழுத்துப் பிரதியை எழுத பிரேம் பிஹாரி நரேன் ரைசாதா நியமிக்கப்படுதல்", "நந்தலால் போஸ் தலைமையில் சாந்திநிகேதன் கலைஞர்களால் பக்கங்கள் அலங்கரிக்கப்பட்டு ஒளிவூட்டப்படுதல்", "அவையின் 284 உறுப்பினர்கள் 3 அசல் பிரதிகளில் கையெழுத்திடுதல்", "நாடாளுமன்ற நூலகத்தில் ஹீலியம் நிரப்பப்பட்ட கண்ணாடிப் பெட்டிகளில் அசல் பிரதிகள் பாதுகாப்பபடுதல்"],
    "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (Raizada commissioned, Nov 1949) -> 2 (Shantiniketan artists decorated pages, Dec 1949-Jan 1950) -> 3 (284 members signed, Jan 24, 1950) -> 4 (Preserved in helium cases in Parliament Library, Post-1950).",
    "சரியான காலவரிசை: 1 (ரைசாதா நியமனம், நவ 1949) -> 2 (சாந்திநிகேதன் ஓவியங்கள், டிச 1949-ஜன 1950) -> 3 (284 உறுப்பினர்கள் கையெழுத்து, ஜன 24, 1950) -> 4 (ஹீலியம் பெட்டிகளில் பாதுகாப்பு, 1950-க்குப் பின்).",
    "Correct. 1 (Nov 1949) -> 2 (Dec 1949-Jan 1950) -> 3 (Jan 24, 1950) -> 4 (Post-1950) is exact.", "சரி. 1 (நவ 1949) -> 2 (டிச 1949-ஜன 1950) -> 3 (ஜன 24, 1950) -> 4 (1950-க்குப் பின்) துல்லியமானது.",
    "Incorrect. Raizada was commissioned (1) before Shantiniketan artists decorated the written pages (2).", "தவறு. ரைசாதா நியமனம் (1) சாந்திநிகேதன் ஓவியங்களுக்கு முந்தியது (2).",
    "Incorrect. Decoration (2) was completed before signing on Jan 24, 1950 (3).", "தவறு. ஓவிய அலங்காரம் (2) கையெழுத்திடுவதற்கு முந்தியது (3).",
    "Incorrect. Calligraphy commissioning (1) was the earliest step in this sequence.", "தவறு. கையெழுத்து நியமனம் (1) மிக முந்தையது.",
    "TNPSC Trap: Original Constitution was handwritten by Prem Behari Narain Raizada, decorated by Nandalal Bose, signed on Jan 24, 1950, and preserved in HELIUM cases.",
    "TNPSC பொறி: அசல் அரசியலமைப்பு பிரேம் பிஹாரி நரேன் ரைசாதாவால் கையால் எழுதப்பட்டது, நந்தலால் போஸால் அலங்கரிக்கப்பட்டது, ஜனவரி 24, 1950 இல் கையெழுத்திடப்பட்டது, மேலும் ஹீலியம் பெட்டிகளில் பாதுகாக்கப்படுகிறது.",
    "Prem Behari Narain Raizada used 303 nibs to write the manuscript and took 6 months.",
    "பிரேம் பிஹாரி நரேன் ரைசாதா 303 நிப்களைப் பயன்படுத்தி 6 மாதங்களில் எழுதினார்.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Handwritten Constitution", "Calligraphy", "Decoration of Constitution", "Constitution Signing"]
))

# MIC_CHRONO_021
questions.append(make_chrono_q(
    "MIC_CHRONO_021", "Chronology",
    "Identify the correct chronological order of the major thematic debate sessions in the Constituent Assembly:\n1. Debates on Objectives Resolution and Preamble principles\n2. Debates on Fundamental Rights (Part III) and Directive Principles (Part IV)\n3. Debates on Official Language and the Munshi-Ayyangar Formula\n4. Final vote passing the Constitution as settled by the Assembly",
    "அரசியலமைப்பு அவையில் நடைபெற்ற முக்கியப் பொருள் சார்ந்த விவாத அமர்வுகளின் சரியான காலவரிசையை அடையாளம் காணவும்:\n1. குறிக்கோள்கள் தீர்மானம் மற்றும் முகப்புரைக் கோட்பாடுகள் பற்றிய விவாதங்கள்\n2. அடிப்படை உரிமைகள் (பகுதி III) மற்றும் அரசு நெறிமுறைக் கோட்பாடுகள் (பகுதி IV) பற்றிய விவாதங்கள்\n3. ஆட்சி மொழி மற்றும் முன்ஷி-அய்யங்கார் சூத்திரம் பற்றிய விவாதங்கள்\n4. அவையால் தீர்மானிக்கப்பட்ட அரசியலமைப்பை நிறைவேற்றும் இறுதி வாக்கெடுப்பு",
    ["Debates on Objectives Resolution and Preamble principles", "Debates on Fundamental Rights (Part III) and Directive Principles (Part IV)", "Debates on Official Language and the Munshi-Ayyangar Formula", "Final vote passing the Constitution as settled by the Assembly"],
    ["குறிக்கோள்கள் தீர்மானம் மற்றும் முகப்புரைக் கோட்பாடுகள் பற்றிய விவாதங்கள்", "அடிப்படை உரிமைகள் (பகுதி III) மற்றும் அரசு நெறிமுறைக் கோட்பாடுகள் (பகுதி IV) பற்றிய விவாதங்கள்", "ஆட்சி மொழி மற்றும் முன்ஷி-அய்யங்கார் சூத்திரம் பற்றிய விவாதங்கள்", "அவையால் தீர்மானிக்கப்பட்ட அரசியலமைப்பை நிறைவேற்றும் இறுதி வாக்கெடுப்பு"],
    "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (Objectives Resolution debates, Dec 1946-Jan 1947) -> 2 (FR & DPSP debates, Nov-Dec 1948) -> 3 (Language debates & Munshi-Ayyangar formula, Sept 1949) -> 4 (Final vote, Nov 26, 1949).",
    "சரியான காலவரிசை: 1 (குறிக்கோள்கள் தீர்மான விவாதம், டிச 1946-ஜன 1947) -> 2 (அடிப்படை உரிமைகள் விவாதம், நவ-டிச 1948) -> 3 (ஆட்சி மொழி முன்ஷி-அய்யங்கார் சூத்திர விவாதம், செப் 1949) -> 4 (இறுதி வாக்கெடுப்பு, நவ 26, 1949).",
    "Correct. 1 (Dec 1946) -> 2 (Nov 1948) -> 3 (Sept 1949) -> 4 (Nov 26, 1949) is exact.", "சரி. 1 (டிச 1946) -> 2 (நவ 1948) -> 3 (செப் 1949) -> 4 (நவ 26, 1949) துல்லியமானது.",
    "Incorrect. Objectives Resolution debates (1) occurred before FR debates (2).", "தவறு. குறிக்கோள்கள் தீர்மான விவாதம் (1) அடிப்படை உரிமைகள் விவாதத்திற்கு முந்தியது (2).",
    "Incorrect. FR debates (2) occurred before Official Language debates in Sept 1949 (3).", "தவறு. அடிப்படை உரிமைகள் விவாதம் (2) ஆட்சி மொழி விவாதத்திற்கு முந்தியது (3).",
    "Incorrect. Objectives Resolution debates (1) was the earliest among these.", "தவறு. குறிக்கோள்கள் தீர்மான விவாதம் (1) மிக முந்தையது.",
    "TNPSC Trap: Official Language debate was one of the last major debates, settled via Munshi-Ayyangar Formula in September 1949.",
    "TNPSC பொறி: ஆட்சி மொழி விவாதம் கடைசி முக்கிய விவாதங்களில் ஒன்றாகும், இது செப்டம்பர் 1949 இல் முன்ஷி-அய்யங்கார் சூத்திரம் மூலம் தீர்க்கப்பட்டது.",
    "Part XVII of the Constitution contains provisions relating to Official Languages.",
    "அரசியலமைப்பின் பகுதி XVII ஆட்சி மொழி தொடர்பான விதங்களைக் கொண்டுள்ளது.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Constitutional Debates", "Objectives Resolution", "Adoption of Constitution"]
))

# MIC_CHRONO_022
questions.append(make_chrono_q(
    "MIC_CHRONO_022", "Chronology",
    "Arrange the following steps in the work of the Advisory Committee on Fundamental Rights and Minorities in correct chronological order:\n1. Sardar Vallabhbhai Patel appointed Chairman of the main Advisory Committee\n2. J.B. Kripalani heads the Fundamental Rights Sub-Committee\n3. Submission of the Interim Report on Fundamental Rights to the Assembly\n4. Submission of the Report on Minorities Rights recommending abolition of separate electorates",
    "அடிப்படை உரிமைகள் மற்றும் சிறுபான்மையினர் ஆலோசனைக் குழுவின் பணியில் உள்ள பின்வரும் படிகளை சரியான காலவரிசையில் அமைக்கவும்:\n1. முதன்மை ஆலோசனைக் குழுவின் தலைவராக சர்தார் வல்லபாய் படேல் நியமிக்கப்படுதல்\n2. அடிப்படை உரிமைகள் துணைக் குழுவிற்கு ஜெ.பி. கிருபளானி தலைமை தாங்குதல்\n3. அடிப்படை உரிமைகள் குறித்த இடைக்கால அறிக்கை அவையிடம் சமர்ப்பிக்கப்படுதல்\n4. தனித் தொகுதிகளை ஒழிக்கப் பரிந்துரைக்கும் சிறுபான்மையினர் உரிமை அறிக்கை சமர்ப்பிக்கப்படுதல்",
    ["Sardar Vallabhbhai Patel appointed Chairman of the main Advisory Committee", "J.B. Kripalani heads the Fundamental Rights Sub-Committee", "Submission of the Interim Report on Fundamental Rights to the Assembly", "Submission of the Report on Minorities Rights recommending abolition of separate electorates"],
    ["முதன்மை ஆலோசனைக் குழுவின் தலைவராக சர்தார் வல்லபாய் படேல் நியமிக்கப்படுதல்", "அடிப்படை உரிமைகள் துணைக் குழுவிற்கு ஜெ.பி. கிருபளானி தலைமை தாங்குதல்", "அடிப்படை உரிமைகள் குறித்த இடைக்கால அறிக்கை அவையிடம் சமர்ப்பிக்கப்படுதல்", "தனித் தொகுதிகளை ஒழிக்கப் பரிந்துரைக்கும் சிறுபான்மையினர் உரிமை அறிக்கை சமர்ப்பிக்கப்படுதல்"],
    "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (Patel appointed Advisory Chair, Jan 24, 1947) -> 2 (Kripalani heads FR Sub-Committee, Feb 1947) -> 3 (Interim FR Report, April 1947) -> 4 (Minorities Report recommending ending separate electorates, August 1947).",
    "சரியான காலவரிசை: 1 (படேல் தலைவர் நியமனம், ஜன 24, 1947) -> 2 (கிருபளானி துணைக் குழுத் தலைவர், பிப் 1947) -> 3 (அடிப்படை உரிமை இடைக்கால அறிக்கை, ஏப்ரல் 1947) -> 4 (சிறுபான்மையினர் அறிக்கை, ஆகஸ்ட் 1947).",
    "Correct. 1 (Jan 1947) -> 2 (Feb 1947) -> 3 (April 1947) -> 4 (Aug 1947) is exact.", "சரி. 1 (ஜன 1947) -> 2 (பிப் 1947) -> 3 (ஏப்ரல் 1947) -> 4 (ஆகஸ்ட் 1947) துல்லியமானது.",
    "Incorrect. Main Advisory Committee was appointed (1) before Kripalani headed FR Sub-Committee (2).", "தவறு. முதன்மை ஆலோசனைக் குழு நியமனம் (1) துணைக் குழு நியமனத்திற்கு முந்தியது (2).",
    "Incorrect. FR Sub-Committee was formed (2) before Interim Report was submitted in April 1947 (3).", "தவறு. துணைக் குழு நியமனம் (2) இடைக்கால அறிக்கைக்கு முந்தியது (3).",
    "Incorrect. Main Advisory Committee appointment (1) was the earliest step.", "தவறு. முதன்மை ஆலோசனைக் குழு நியமனம் (1) மிக முந்தையது.",
    "TNPSC Trap: Main Advisory Committee Chair = Sardar Patel. Fundamental Rights Sub-Committee Chair = J.B. Kripalani. Minorities Sub-Committee Chair = H.C. Mookherjee.",
    "TNPSC பொறி: முதன்மை ஆலோசனைக் குழுத் தலைவர் = சர்தார் படேல். அடிப்படை உரிமைகள் துணைக் குழுத் தலைவர் = ஜெ.பி. கிருபளானி. சிறுபான்மையினர் துணைக் குழுத் தலைவர் = எச்.சி. முகர்ஜி.",
    "The decision to abolish separate electorates was a momentous step towards secular democratic integration.",
    "தனித் தொகுதிகளை ஒழிக்கும் முடிவு மதச்சார்பற்ற ஜனநாயக ஒருங்கிணைப்பிற்கான ஒரு முக்கிய அடியாகும்.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Advisory Committee", "Important Committees"]
))

# MIC_CHRONO_023
questions.append(make_chrono_q(
    "MIC_CHRONO_023", "Chronology",
    "Which of the following is the correct chronological order of Cabinet Mission Plan implementation steps?\n1. Arrival of the Cabinet Mission in New Delhi\n2. Announcement of the Cabinet Mission Constitutional Scheme\n3. Completion of elections for 296 British Indian seats in Constituent Assembly\n4. Opening of the first session of the Constituent Assembly in New Delhi",
    "கேபினட் தூதுக்குழு திட்டத்தை அமல்படுத்தும் படிகளின் சரியான காலவரிசை எது?\n1. புதுடெல்லியில் கேபினட் தூதுக்குழு வருகை\n2. கேபினட் தூதுக்குழுவின் அரசியலமைப்பு திட்டம் அறிவிக்கப்படுதல்\n3. அரசியலமைப்பு அவையின் 296 பிரிட்டிஷ் இந்திய இடங்களுக்கான தேர்தல்கள் நிறைவடைதல்\n4. புதுடெல்லியில் அரசியலமைப்பு அவையின் முதல் அமர்வு தொடங்குதல்",
    ["Arrival of the Cabinet Mission in New Delhi", "Announcement of the Cabinet Mission Constitutional Scheme", "Completion of elections for 296 British Indian seats in Constituent Assembly", "Opening of the first session of the Constituent Assembly in New Delhi"],
    ["புதுடெல்லியில் கேபினட் தூதுக்குழு வருகை", "கேபினட் தூதுக்குழுவின் அரசியலமைப்பு திட்டம் அறிவிக்கப்படுதல்", "அரசியலமைப்பு அவையின் 296 பிரிட்டிஷ் இந்திய இடங்களுக்கான தேர்தல்கள் நிறைவடைதல்", "புதுடெல்லியில் அரசியலமைப்பு அவையின் முதல் அமர்வு தொடங்குதல்"],
    "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (Arrival, March 24, 1946) -> 2 (Scheme announced, May 16, 1946) -> 3 (Elections completed, July-August 1946) -> 4 (First session opened, Dec 9, 1946).",
    "சரியான காலவரிசை: 1 (வருகை, மார்ச் 24, 1946) -> 2 (திட்டம் அறிவிப்பு, மே 16, 1946) -> 3 (தேர்தல் முடிவு, ஜூலை-ஆகஸ்ட் 1946) -> 4 (முதல் அமர்வு தொடக்கம், டிச 9, 1946).",
    "Correct. 1 (March 1946) -> 2 (May 1946) -> 3 (July-Aug 1946) -> 4 (Dec 1946) is exact.", "சரி. 1 (மார்ச் 1946) -> 2 (மே 1946) -> 3 (ஜூலை-ஆகஸ்ட் 1946) -> 4 (டிச 1946) துல்லியமானது.",
    "Incorrect. Arrival (March 1946) preceded Scheme announcement (May 1946).", "தவறு. வருகை (மார்ச் 1946) திட்டம் அறிவிப்பிற்கு முந்தியது (மே 1946).",
    "Incorrect. Scheme announcement (May 1946) preceded elections (July-Aug 1946).", "தவறு. திட்டம் அறிவிப்பு (மே 1946) தேர்தலுக்கு முந்தியது (ஜூலை-ஆகஸ்ட் 1946).",
    "Incorrect. Arrival (March 1946) was the earliest step.", "தவறு. வருகை (மார்ச் 1946) மிக முந்தையது.",
    "TNPSC Trap: Cabinet Mission arrived = March 24, 1946. Plan announced = May 16, 1946. Elections = July-Aug 1946. First Session = Dec 9, 1946.",
    "TNPSC பொறி: கேபினட் தூதுக்குழு வருகை = மார்ச் 24, 1946. திட்டம் அறிவிப்பு = மே 16, 1946. தேர்தல் = ஜூலை-ஆகஸ்ட் 1946. முதல் அமர்வு = டிசம்பர் 9, 1946.",
    "Lord Pethick-Lawrence, Sir Stafford Cripps, and A.V. Alexander were the three members of Cabinet Mission.",
    "பெதிக்-லாரன்ஸ் பிரபு, சர் ஸ்டாஃபோர்ட் கிரிப்ஸ், ஏ.வி. அலெக்சாண்டர் ஆகியோர் கேபினட் தூதுக்குழுவின் மூன்று உறுப்பினர்களாவர்.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Cabinet Mission Plan", "Constituent Assembly Election", "First Meeting"]
))

# MIC_CHRONO_024
questions.append(make_chrono_q(
    "MIC_CHRONO_024", "Chronology",
    "Identify the correct chronological sequence of Presidential Elections & Transition Milestones in the Constituent Assembly:\n1. Dr. Sachchidananda Sinha elected Temporary President of Constituent Assembly\n2. Dr. Rajendra Prasad elected Permanent President of Constituent Assembly\n3. Dr. Rajendra Prasad elected as the first President of Independent India by Constituent Assembly\n4. Dr. Rajendra Prasad sworn in as first President of the Republic of India",
    "அரசியலமைப்பு அவையின் குடியரசுத் தலைவர் தேர்தல்கள் மற்றும் மாற்ற மைல்கற்களின் சரியான காலவரிசையை அடையாளம் காணவும்:\n1. டாக்டர் சச்சிதானந்த சின்ஹா அரசியலமைப்பு அவையின் தற்காலிகத் தலைவராகத் தேர்ந்தெடுக்கப்படுதல்\n2. டாக்டர் ராஜேந்திர பிரசாத் அரசியலமைப்பு அவையின் நிரந்தரத் தலைவராகத் தேர்ந்தெடுக்கப்படுதல்\n3. டாக்டர் ராஜேந்திர பிரசாத் சுதந்திர இந்தியாவின் முதல் குடியரசுத் தலைவராக அவையால் தேர்ந்தெடுக்கப்படுதல்\n4. டாக்டர் ராஜேந்திர பிரசாத் இந்தியக் குடியரசின் முதல் தலைவராகப் பிரமாணம் செய்துகொள்ளுதல்",
    ["Dr. Sachchidananda Sinha elected Temporary President of Constituent Assembly", "Dr. Rajendra Prasad elected Permanent President of Constituent Assembly", "Dr. Rajendra Prasad elected as the first President of Independent India by Constituent Assembly", "Dr. Rajendra Prasad sworn in as first President of the Republic of India"],
    ["டாக்டர் சச்சிதானந்த சின்ஹா அரசியலமைப்பு அவையின் தற்காலிகத் தலைவராகத் தேர்ந்தெடுக்கப்படுதல்", "டாக்டர் ராஜேந்திர பிரசாத் அரசியலமைப்பு அவையின் நிரந்தரத் தலைவராகத் தேர்ந்தெடுக்கப்படுதல்", "டாக்டர் ராஜேந்திர பிரசாத் சுதந்திர இந்தியாவின் முதல் குடியரசுத் தலைவராக அவையால் தேர்ந்தெடுக்கப்படுதல்", "டாக்டர் ராஜேந்திர பிரசாத் இந்தியக் குடியரசின் முதல் தலைவராகப் பிரமாணம் செய்துகொள்ளுதல்"],
    "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (Sinha Temp President, Dec 9, 1946) -> 2 (Rajendra Prasad CA President, Dec 11, 1946) -> 3 (Rajendra Prasad elected 1st President of India, Jan 24, 1950) -> 4 (Rajendra Prasad sworn in on Republic Day, Jan 26, 1950).",
    "சரியான காலவரிசை: 1 (சின்ஹா தற்காலிகத் தலைவர், டிச 9, 1946) -> 2 (ராஜேந்திர பிரசாத் அவைத் தலைவர், டிச 11, 1946) -> 3 (முதல் குடியரசுத் தலைவர் தேர்வு, ஜன 24, 1950) -> 4 (குடியரசுத் தலைவர் பிரமாணம், ஜன 26, 1950).",
    "Correct. 1 (Dec 9, 1946) -> 2 (Dec 11, 1946) -> 3 (Jan 24, 1950) -> 4 (Jan 26, 1950) is exact.", "சரி. 1 (டிச 9, 1946) -> 2 (டிச 11, 1946) -> 3 (ஜன 24, 1950) -> 4 (ஜன 26, 1950) துல்லியமானது.",
    "Incorrect. Sinha elected temp President (1) before Rajendra Prasad elected CA President (2).", "தவறு. சின்ஹா தற்காலிகத் தலைவராகத் தேர்வு (1) ராஜேந்திர பிரசாத் தேர்வுக்கு முந்தியது (2).",
    "Incorrect. Rajendra Prasad elected CA President in Dec 1946 (2) before elected 1st President of India in Jan 1950 (3).", "தவறு. ராஜேந்திர பிரசாத் அவைத் தலைவராகத் தேர்வு (2) குடியரசுத் தலைவர் தேர்வுக்கு முந்தியது (3).",
    "Incorrect. Sinha elected temp President (1) was the earliest.", "தவறு. சின்ஹா தற்காலிகத் தலைவராகத் தேர்வு (1) மிக முந்தையது.",
    "TNPSC Trap: Dr. Rajendra Prasad was ELECTED first President of India on Jan 24, 1950 and SWORN IN on Jan 26, 1950.",
    "TNPSC பொறி: டாக்டர் ராஜேந்திர பிரசாத் ஜனவரி 24, 1950 அன்று முதல் குடியரசுத் தலைவராகத் தேர்ந்தெடுக்கப்பட்டு, ஜனவரி 26, 1950 அன்று பிரமாணம் செய்தார்.",
    "Dr. Rajendra Prasad was the longest-serving President of India (1950 to 1962).",
    "டாக்டர் ராஜேந்திர பிரசாத் மிக நீண்ட காலம் பணியாற்றிய இந்தியக் குடியரசுத் தலைவர் ஆவார் (1950 முதல் 1962 வரை).",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Temporary President", "Permanent President", "Important Personalities"]
))

# MIC_CHRONO_025
questions.append(make_chrono_q(
    "MIC_CHRONO_025", "Chronology",
    "Arrange the following grand milestones in the overall making of the Indian Constitution in correct chronological order:\n1. M.N. Roy puts forward the pioneer proposal for an Indian Constituent Assembly\n2. Cabinet Mission Plan proposes a single Constituent Assembly for undivided India\n3. Adoption and enactment of the Constitution by the Constituent Assembly\n4. Commencement of the Constitution of India celebrating Republic Day",
    "இந்திய அரசியலமைப்பு உருவாக்கத்தின் பின்வரும் ஒட்டுமொத்தப் பெருமைமிக்க மைல்கற்களை சரியான காலவரிசையில் அமைக்கவும்:\n1. எம்.என். ராய் இந்திய அரசியலமைப்பு நிர்ணய அவைகளுக்கான முன்னோடி முன்மொழிவை வழங்குதல்\n2. கேபினட் தூதுக்குழு திட்டம் பிரிக்கப்படாத இந்தியாவிற்கு ஒரே ஒரு அவையைப் பரிந்துரைத்தல்\n3. அரசியலமைப்பு அவையால் அரசியலமைப்பு ஏற்றுக்கொள்ளப்பட்டு இயற்றப்படுதல்\n4. குடியரசு தினத்தைக் கொண்டாடும் வகையில் இந்திய அரசியலமைப்பு நடைமுறைக்கு வருதல்",
    ["M.N. Roy puts forward the pioneer proposal for an Indian Constituent Assembly", "Cabinet Mission Plan proposes a single Constituent Assembly for undivided India", "Adoption and enactment of the Constitution by the Constituent Assembly", "Commencement of the Constitution of India celebrating Republic Day"],
    ["எம்.என். ராய் இந்திய அரசியலமைப்பு நிர்ணய அவைகளுக்கான முன்னோடி முன்மொழிவை வழங்குதல்", "கேபினட் தூதுக்குழு திட்டம் பிரிக்கப்படாத இந்தியாவிற்கு ஒரே ஒரு அவையைப் பரிந்துரைத்தல்", "அரசியலமைப்பு அவையால் அரசியலமைப்பு ஏற்றுக்கொள்ளப்பட்டு இயற்றப்படுதல்", "குடியரசு தினத்தைக் கொண்டாடும் வகையில் இந்திய அரசியலமைப்பு நடைமுறைக்கு வருதல்"],
    "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (M.N. Roy proposal, 1934) -> 2 (Cabinet Mission Plan, May 1946) -> 3 (Adoption of Constitution, Nov 26, 1949) -> 4 (Commencement of Constitution, Jan 26, 1950).",
    "சரியான காலவரிசை: 1 (எம்.என். ராய் முன்மொழிவு, 1934) -> 2 (கேபினட் திட்டம், மே 1946) -> 3 (அரசியலமைப்பு ஏற்பு, நவ 26, 1949) -> 4 (அரசியலமைப்பு நடைமுறை, ஜன 26, 1950).",
    "Correct. 1 (1934) -> 2 (1946) -> 3 (Nov 26, 1949) -> 4 (Jan 26, 1950) is exact.", "சரி. 1 (1934) -> 2 (1946) -> 3 (நவ 26, 1949) -> 4 (ஜன 26, 1950) துல்லியமானது.",
    "Incorrect. M.N. Roy proposal in 1934 (1) was long before Cabinet Mission in 1946 (2).", "தவறு. எம்.என். ராய் முன்மொழிவு (1934) கேபினட் திட்டத்திற்கு முந்தியது (1946).",
    "Incorrect. Cabinet Mission in 1946 (2) was before Adoption in Nov 1949 (3).", "தவறு. கேபினட் திட்டம் (1946) அரசியலமைப்பு ஏற்பிற்கு முந்தியது (நவ 1949).",
    "Incorrect. M.N. Roy proposal in 1934 (1) was the earliest.", "தவறு. எம்.என். ராய் முன்மொழிவு (1934) மிக முந்தையது.",
    "TNPSC Trap: M.N. Roy (1934) -> Cabinet Mission (1946) -> Adoption (Nov 26, 1949) -> Commencement (Jan 26, 1950).",
    "TNPSC பொறி: எம்.என். ராய் (1934) -> கேபினட் திட்டம் (1946) -> ஏற்பு (நவ 26, 1949) -> நடைமுறை (ஜன 26, 1950).",
    "The Constitution of India is the longest written constitution of any sovereign country in the world.",
    "இந்திய அரசியலமைப்பு உலகிலேயே மிக நீளமான எழுதப்பட்ட அரசியலமைப்பாகும்.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Demand for Constituent Assembly", "Cabinet Mission Plan", "Constitution Adoption", "Constitution Enforcement"]
))
